		Thể tích $V$ của khối chóp trên là $V = \displaystyle\frac{1}{3} S_{ABC} \cdot SA = \displaystyle\frac{1}{3} \cdot \displaystyle\frac{1}{2} \cdot AB \cdot BC \cdot SA = \displaystyle\frac{1}{6} \cdot a \cdot a \cdot a\sqrt{3} = \displaystyle\frac{a^3\sqrt{3}}{6}$.

\begin{itemchoice}
			\itemch Ta có $\overrightarrow{AC} = (20-15; 60-10; 50+50) = (5;50;100) = 5(1;10;20) = 5\vec{u}$. Phương trình chính tắc là $\displaystyle \frac{x-20}{1} = \displaystyle \frac{y-60}{10} = \displaystyle \frac{z-50}{20}$. Vậy ý a) Đúng.
			\itemch Gọi $B'$ là hình chiếu vuông góc của $B$ lên mặt phẳng $(Oxy)$, theo đề bài $B'(17,5; 35; 5)$. Phương trình tham số đường thẳng $d$ đi qua $B'$ có vectơ chỉ phương $\vec{u}=(2;1;0)$ là: $\begin{cases} x=17,5+2h \\ y=35+h \\ z=5 \end{cases}$. Điểm $M \in d \Rightarrow M(17,5+2h; 35+h; 5)$. Khoảng cách $AM$ ngắn nhất khi $\overrightarrow{AM} \perp \vec{u}_d$. Sau khi giải phương trình $\overrightarrow{AM}.\vec{u}_d = 0$, ta được $h=-6$, suy ra $M(5,5; 29; 5)$, nên $a'+b'+c'=39,5 \ne 34$. Vậy ý b) Sai.
			\itemch $B = AC \cap (Oxy) \Rightarrow B \in AC$. Phương trình $AC$ dạng tham số là $\begin{cases} x=20+t \\ y=60+10t \\ z=50+20t \end{cases}$. Cho $z=0 \Rightarrow 50+20t=0 \Rightarrow t=-2,5 \Rightarrow B(17,5; 35; 0)$. Suy ra $a+b+c=17,5+35+0=52,5$. Vậy ý c) Đúng.
			\itemch Quãng đường tia laser đi được trong nước sau 10 ns là: $\displaystyle \int_{0}^{10} (0,22 + 0,01t)dt = \left[ 0,22t + 0,005t^2 \right]_0^{10} = 2,2 + 0,5 = 2,7 \text{ (m)} \ne 2,475$. Vậy ý d) Sai.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có $f'(x) = -\displaystyle \frac{4}{x^2} + 1$. Tại $x=-4$: $f'(-4) = -\displaystyle \frac{4}{16} + 1 = 0,75 = \displaystyle \frac{3}{4}$. Vậy ý a) Sai.
			\itemch $f'(x) = -\displaystyle \frac{4}{x^2} + 1 = \displaystyle \frac{x^2 - 4}{x^2}$. Vậy ý b) Đúng.
			\itemch $f'(x) = 0 \Leftrightarrow x^2=4 \Leftrightarrow x=\pm 2$. Trên đoạn $[1;3]$, ta xét tại $x=1, x=2, x=3$: $f(1)=6, f(2)=5, f(3)=16/3$. Do đó $M=6, m=5$. $M-m=1$. Vậy ý c) Đúng.
			\itemch Phương trình $f'(x)=0$ có hai nghiệm là $x=2$ và $x=-2$, tổng là $0 \ne 4$. Vậy ý d) Sai.
		\end{itemchoice}
